-- 导出  表 yiti.addrbook_employee 结构
CREATE TABLE IF NOT EXISTS `addrbook_employee` (
  `emp_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '员工工号',
  `emp_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '员工姓名',
  `mobile` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机号',
  `email` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邮箱',
  `org_code` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属机构代码',
  `org_name` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属机构名称',
  `position` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '岗位',
  `self_desc` text COLLATE utf8mb4_general_ci COMMENT '自我描述',
  `responsible_product_ids` text COLLATE utf8mb4_general_ci COMMENT '负责产品ID列表(JSON数组)',
  `status` varchar(20) COLLATE utf8mb4_general_ci DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE-在职, RESIGNED-离职',
  `maintainer_emp_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '维护人工号',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` int DEFAULT '0' COMMENT '删除标记：0-未删除, 1-已删除',
  PRIMARY KEY (`emp_id`),
  KEY `idx_org_code` (`org_code`),
  KEY `idx_maintainer` (`maintainer_emp_id`),
  KEY `idx_deleted` (`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='通讯录员工表';

