-- 导出  表 yiti.audit_log 结构
CREATE TABLE IF NOT EXISTS `audit_log` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '日志ID',
  `trace_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '链路追踪ID',
  `emp_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人工号',
  `emp_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作人姓名',
  `biz_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务类型',
  `biz_action` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务动作',
  `resource_url` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '资源URL',
  `request_method` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请求方法',
  `request_params` text COLLATE utf8mb4_general_ci COMMENT '请求参数（脱敏）',
  `response_status` int DEFAULT NULL COMMENT '响应状态码',
  `error_msg` text COLLATE utf8mb4_general_ci COMMENT '错误信息',
  `ip_address` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'IP地址',
  `user_agent` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户代理',
  `execution_time` int DEFAULT NULL COMMENT '执行耗时（毫秒）',
  `reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作原因（高危动作必填）',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_emp_id` (`emp_id`),
  KEY `idx_biz_type` (`biz_type`),
  KEY `idx_created_time` (`created_time`),
  KEY `idx_trace_id` (`trace_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='审计日志表';

