-- 导出  表 yiti.biz_file_rel 结构
CREATE TABLE IF NOT EXISTS `biz_file_rel` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联ID',
  `biz_type` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型(BizType或业务域)',
  `biz_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务ID(字符串)',
  `file_object_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件对象ID',
  `file_role` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用途：ATTACHMENT/PHOTO/...',
  `created_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz_file` (`biz_type`,`biz_id`,`file_object_id`),
  KEY `idx_biz` (`biz_type`,`biz_id`),
  KEY `idx_file` (`file_object_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='业务-附件关联表';

