-- 导出  表 yiti.biz_process_map 结构
CREATE TABLE IF NOT EXISTS `biz_process_map` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '映射ID',
  `business_key` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务键（格式：BIZ_TYPE:{id}）',
  `biz_type` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型',
  `biz_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务ID',
  `process_definition_key` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程定义KEY',
  `process_instance_id` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Flowable流程实例ID',
  `start_user` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '发起人工号',
  `current_assignee` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '当前处理人工号',
  `candidate_groups` text COLLATE utf8mb4_general_ci COMMENT '候选组列表（JSON数组）',
  `process_status` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'RUNNING' COMMENT '流程状态：RUNNING-运行中, COMPLETED-已完成, CANCELLED-已取消',
  `title` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程标题',
  `start_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '发起时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_business_key` (`business_key`),
  UNIQUE KEY `uk_process_instance` (`process_instance_id`),
  KEY `idx_biz_type_id` (`biz_type`,`biz_id`),
  KEY `idx_start_user` (`start_user`),
  KEY `idx_current_assignee` (`current_assignee`),
  KEY `idx_status` (`process_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='业务流程映射表';

