-- 导出  表 yiti.cust_lead 结构
CREATE TABLE IF NOT EXISTS `cust_lead` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '线索ID',
  `lead_no` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '线索编号',
  `lead_op` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'CREATE' COMMENT '线索操作：CREATE/UPDATE/DELETE',
  `source_cust_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关联客户ID(UPDATE/DELETE时必填)',
  `prev_lead_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '上一版本线索ID(UPDATE/DELETE时必填)',
  `version_no` int NOT NULL DEFAULT '1' COMMENT '版本号(从1开始)',
  `is_latest` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否最新版本(1-是,0-否)',
  `cust_name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户名称',
  `unified_credit_code` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '统一社会信用代码(纳税人识别号)',
  `tag_ids` text COLLATE utf8mb4_general_ci COMMENT '标签ID列表(JSON数组)',
  `contact_person` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系人',
  `contact_mobile` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `industry` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属行业',
  `group_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属集团类型(字典)',
  `customer_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户类型(字典)',
  `is_keystone` tinyint(1) DEFAULT NULL COMMENT '是否基石客户(1-是,0-否)',
  `enterprise_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '企业类型(字典)',
  `group_name` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属集团名称',
  `is_account_opened` tinyint(1) DEFAULT NULL COMMENT '是否开户(1-是,0-否)',
  `customer_desc` text COLLATE utf8mb4_general_ci COMMENT '客户说明',
  `credit_amount` decimal(20,4) DEFAULT NULL COMMENT '授信金额',
  `credit_exposure_amount` decimal(20,4) DEFAULT NULL COMMENT '授信敞口金额',
  `lead_source` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '线索来源',
  `lead_status` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'DRAFT' COMMENT '线索状态：DRAFT-草稿, SUBMITTED-已提交, IN_APPROVAL-审批中, APPROVED-已通过, REJECTED-已驳回',
  `owner_org_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '归属机构代码',
  `assigned_to` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分配用户',
  `created_by` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人工号',
  `business_key` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程业务键（LEAD:{id}）',
  `import_batch_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '导入批次ID(批量导入)',
  `process_instance_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程实例ID',
  `remark` text COLLATE utf8mb4_general_ci COMMENT '备注',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint DEFAULT '0' COMMENT '删除标记',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_lead_no` (`lead_no`),
  KEY `idx_owner_org` (`owner_org_id`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_business_key` (`business_key`),
  KEY `idx_status` (`lead_status`),
  KEY `idx_import_batch` (`import_batch_id`),
  KEY `idx_cust_name` (`cust_name`),
  KEY `idx_unified_credit_code` (`unified_credit_code`),
  KEY `idx_source_cust` (`source_cust_id`),
  KEY `idx_lead_op_status` (`lead_op`,`lead_status`),
  KEY `idx_is_latest` (`is_latest`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户线索表';

