CREATE TABLE IF NOT EXISTS `cust_master` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户ID',
  `cust_no` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户编号',
  `cust_name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户名称',
  `unified_credit_code` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '统一社会信用代码(纳税人识别号)',
  `contact_person` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系人',
  `contact_mobile` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `industry` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属行业',
  `group_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属集团类型(字典)',
  `customer_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户类型(字典)',
  `is_keystone` tinyint(1) DEFAULT NULL COMMENT '是否基石客户(1-是,0-否)',
  `enterprise_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '企业类型(字典)',
  `group_name` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属集团名称',
  `is_account_opened` tinyint(1) DEFAULT NULL COMMENT '是否开户(1-是,0-否)',
  `customer_desc` text COLLATE utf8mb4_general_ci COMMENT '客户说明',
  `credit_amount` decimal(20,4) DEFAULT NULL COMMENT '授信金额',
  `credit_exposure_amount` decimal(20,4) DEFAULT NULL COMMENT '授信敞口金额',
  `owner_org_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源机构代码（不承载可见性）',
  `lead_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源线索ID',
  `status` varchar(20) COLLATE utf8mb4_general_ci DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE-正常, INACTIVE-停用',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '删除标记(0-否,1-是)',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cust_no` (`cust_no`),
  UNIQUE KEY `uk_cust_name` (`cust_name`),
  KEY `idx_lead_id` (`lead_id`),
  KEY `idx_unified_credit_code` (`unified_credit_code`),
  KEY `idx_deleted` (`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户主档表';

