-- 导出  表 yiti.lead_import_batch 结构
CREATE TABLE IF NOT EXISTS `lead_import_batch` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次ID',
  `batch_no` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次号(展示用)',
  `source_file_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '源文件名',
  `file_md5` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '文件MD5',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'CREATED' COMMENT '状态：CREATED/PENDING_APPROVAL/APPROVED/REJECTED',
  `total_row_count` int NOT NULL DEFAULT '0' COMMENT '总行数',
  `error_row_count` int NOT NULL DEFAULT '0' COMMENT '错误行数',
  `error_summary` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '错误摘要',
  `error_file_object_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '错误明细文件ID(可选)',
  `business_key` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程业务键(LEAD:IMP_{id})',
  `process_instance_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程实例ID',
  `owner_org_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '归属机构',
  `created_by` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_batch_no` (`batch_no`),
  KEY `idx_owner_org` (`owner_org_id`),
  KEY `idx_status` (`status`),
  KEY `idx_created_time` (`created_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='线索导入批次表';

