  `sql_text` text COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SQL语句',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注(reason)',
  `row_count` int DEFAULT NULL COMMENT '影响行数',
  `execution_time_ms` int DEFAULT NULL COMMENT '执行耗时(毫秒)',
  `status` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '状态：RUNNING/SUCCESS/FAILED/TIMEOUT',
  `error_msg` text COLLATE utf8mb4_general_ci COMMENT '错误信息',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_emp_id` (`emp_id`),
  KEY `idx_created_time` (`created_time`),
  KEY `idx_emp_time` (`emp_id`,`created_time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='SQL探查历史';

