-- 导出  表 yiti.support_request 结构
CREATE TABLE IF NOT EXISTS `support_request` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '申请ID(UUID)',
  `request_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申请编号(SR+yyyyMMdd+6位序号)',
  `submit_group_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '同批提交分组ID(多产品拆单时同组共享)',
  `cust_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户ID,逻辑外键→cust_master.id',
  `source_touch_task_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源触达任务ID,逻辑外键→touch_task.id',
  `product_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品ID,逻辑外键→product_info.id',
  `support_dept_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '承接部门ORG_CODE,逻辑外键→EXT_ORG_INFO.org_code',
  `other_demand` text COLLATE utf8mb4_unicode_ci COMMENT '其他需求/补充说明',
  `dispatch_emp_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '派单人工号(部门秘书,仅场景B)',
  `dispatch_time` datetime DEFAULT NULL COMMENT '派单时间',
  `assigned_emp_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '承接办理人工号(场景A=产品负责人,场景B=秘书派单)',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态:DRAFT/IN_APPROVAL/IN_PROGRESS/COMPLETED/REJECTED/CANCELLED',
  `business_key` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程业务键,固定格式SUPPORT:{id}',
  `process_instance_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程实例ID',
  `owner_org_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '归属机构(发起侧ORG_CODE)',
  `created_by` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人工号(发起人)',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人工号',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_request_no` (`request_no`),
  KEY `idx_cust_id` (`cust_id`),
  KEY `idx_support_dept` (`support_dept_id`),
  KEY `idx_assigned_emp` (`assigned_emp_id`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_status` (`status`),
  KEY `idx_business_key` (`business_key`),
  KEY `idx_submit_group` (`submit_group_id`),
  KEY `idx_owner_org` (`owner_org_id`),
  KEY `idx_created_time` (`created_time`),
  KEY `idx_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='中场支持申请表';

