CREATE TABLE IF NOT EXISTS `user_notification` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '通知ID',
  `emp_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '接收人工号',
  `title` varchar(200) COLLATE utf8mb4_general_ci NOT NULL COMMENT '通知标题',
  `content` text COLLATE utf8mb4_general_ci COMMENT '通知内容',
  `notify_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '通知类型：SYSTEM-系统, WORKFLOW-流程, BUSINESS-业务',
  `biz_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务类型',
  `biz_id` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务ID',
  `link_url` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '跳转链接',
  `is_read` tinyint(1) DEFAULT '0' COMMENT '是否已读：1-已读, 0-未读',
  `read_time` datetime DEFAULT NULL COMMENT '阅读时间',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_emp_id_read` (`emp_id`,`is_read`),
  KEY `idx_created_time` (`created_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户通知表';

